package com.akhil.portfolio.portfolio; import jakarta.validation.Valid; import java.util.List; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/holdings") public class HoldingController { final HoldingRepository repo; public HoldingController(HoldingRepository r){repo=r;} @GetMapping public List<Holding> all(){return repo.findAll();} @PostMapping public ResponseEntity<Holding> add(@Valid @RequestBody Holding h){return ResponseEntity.status(HttpStatus.CREATED).body(repo.save(h));} @DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<Void> delete(@PathVariable Long id){repo.deleteById(id);return ResponseEntity.noContent().build();} }